# Base role → its Formativo twin. Same operational permissions, minus the two
# Primer Equipo screens (Cargar GPS, MD+2).
FORMATIVO_TWINS = {
    "Editor": "Editor Formativo",
    "Solo Lectura": "Lectura Formativo",
}
BASE_ROLES = ["Administrador", "Editor", "Solo Lectura"]
SCREEN_CODENAMES = ["view_gps_upload", "view_md2"]


def grant_screens(apps, schema_editor):
    """Give the new screen permissions to the existing roles, so nobody who
    sees Cargar GPS / MD+2 today loses it on deploy, and create the Formativo
    twins without them.

    The permissions are normally created by `post_migrate`, AFTER every
    migration has run — too late for this one — so they are created here.
    """
